const achievementCatalog=[{code:'first_message',title:'بداية اللمة',description:'أرسلت أول رسالة',reward:5,check:m=>m.messages>=1},{code:'social_100',title:'عضو اجتماعي',description:'وصلت إلى 100 رسالة',reward:10,check:m=>m.messages>=100},{code:'social_500',title:'نجم اللمة',description:'وصلت إلى 500 رسالة',reward:25,check:m=>m.messages>=500},{code:'gamer_10',title:'بطل الألعاب',description:'جمعت 10 نقاط من الألعاب',reward:5,check:m=>m.points>=10},{code:'gamer_50',title:'محترف الألعاب',description:'جمعت 50 نقطة من الألعاب',reward:15,check:m=>m.points>=50},{code:'gamer_100',title:'أسطورة الألعاب',description:'جمعت 100 نقطة من الألعاب',reward:30,check:m=>m.points>=100}];
async function grantEligibleAchievements(ctx,chat,userId){const current=member(chat,userId),earned=[];for(const a of achievementCatalog){if(a.check(current)&&awardAchievement(chat,userId,a.code,a.reward))earned.push(a)}if(earned.length){const total=earned.reduce((n,a)=>n+a.reward,0);await ctx.reply(`🏅 إنجاز جديد لـ ${name(ctx.from)}!\n\n${earned.map(a=>`⭐ ${a.title} — ${a.description}`).join('\n')}\n\n🎁 مكافأتك: +${total} نقطة`)}return earned;}
