async function punish(ctx,id,kind,mins=30){const until=Math.floor(Date.now()/1000)+mins*60;if(kind==='ban')return ctx.api.banChatMember(ctx.chat.id,id,{until_date:until});if(kind==='kick'){await ctx.api.banChatMember(ctx.chat.id,id);return ctx.api.unbanChatMember(ctx.chat.id,id)}return ctx.api.restrictChatMember(ctx.chat.id,id,{until_date:until,permissions:{can_send_messages:false}})}
function parseDurationSpec(raw){const m=String(raw||'').trim().match(/^(\d{1,4})\s*(د|دقيقة|دقائق|m|min|h|س|ساعة|ساعات|d|ي|يوم|أيام)?$/i);if(!m)return 0;const n=Number(m[1]),unit=(m[2]||'د').toLowerCase();const factor=['س','ساعة','ساعات','h'].includes(unit)?60:['ي','يوم','أيام','d'].includes(unit)?1440:1;const mins=n*factor;return Number.isInteger(mins)&&mins>=1&&mins<=525600?mins:0}
async function issueWarn(ctx,u,why='مخالفة القوانين'){const n=warn(ctx.chat.id,u.id),s=settings(ctx.chat.id),limit=s.maxwarn||5;addModerationEvent(ctx.chat.id,u.id,ctx.from.id,'إنذار',why);logAdmin(ctx.chat.id,ctx.from.id,'إنذار',u.id,why);await ctx.reply(`⚠️ ها حبيبي ${name(u)}، ${why}. هذا إنذارك ${n}/${limit}`);if(n>=limit){try{const kind=s.punishment||'mute';if(kind==='warn'){await ctx.reply(`⚠️ وصل ${name(u)} للحد المحدد من الإنذارات. اختارت الإدارة نوع العقوبة: تحذير.`);return;}const duration=s.duration||30;await punish(ctx,u.id,kind,duration);addModerationEvent(ctx.chat.id,u.id,ctx.from.id,kind==='mute'?'كتم تلقائي':kind==='kick'?'طرد تلقائي':'حظر تلقائي','بلوغ حد الإنذارات',kind==='mute'||kind==='ban'?duration:0,kind==='mute'||kind==='ban'?Math.floor(Date.now()/1000)+duration*60:0);resetWarnings(ctx.chat.id,u.id);await ctx.reply(`خلص حبيبي، تطبقت عقوبة ${kind==='mute'?'الكتم':kind==='kick'?'الطرد':'الحظر'} وصفرنا الإنذارات حتى تبدي من جديد ❤️`)}catch{await ctx.reply('ما كدرت أطبق العقوبة، تأكد عندي صلاحيات مشرف.')}}}
