function decorateReply(text){
  if(/[\u{1F300}-\u{1FAFF}]/u.test(text)) return text;
  const rules=[[/\b(الله|الحمد|سلام|عافية|يشاف|يحفظ|خير)\b/u,'🤍'],[/(حب|حبيبي|فدوة|تاج راس|مشتاق|اشتياق)/u,'❤️'],[/(دراسة|ادرس|مادة)/u,'📚'],[/(شغل|اشتغل|رزق)/u,'💼'],[/(أكل|جوع|كُل|مطبخ)/u,'🍽️'],[/(نام|نوم|نعسان|تصبح)/u,'😴'],[/(ضحك|هههه|مضحك|😂)/u,'😂'],[/(زعلان|ضوج|بچي|بكاء)/u,'🥲'],[/(صباح)/u,'🌤️'],[/(مساء|ليل)/u,'🌙'],[/(نورت|هلا|مرحبا|أهلاً)/u,'🌹'],[/(لعب|لعبة|تحدي)/u,'🎮'],[/(نغنوغ|بوت)/u,'🤖']];
  for(const [re,emoji] of rules) if(re.test(text)) return `${text} ${emoji}`;
  return `${text} 🙂`;
}
function normalizeAnswer(v){return (v||'').toLowerCase().replace(/[\u064B-\u065F\u0670ـ]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[،.!؟?\s]/g,'').trim()}
function shuffleText(value){
  const chars=Array.from(value);
  for(let i=chars.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[chars[i],chars[j]]=[chars[j],chars[i]];}
  return chars.join(' ');
}
