async function createScheduledBackup(){
  const dir=path.resolve('./backups');await fs.mkdir(dir,{recursive:true});
  const stamp=new Date().toISOString().replace(/[:.]/g,'-');
  const destination=path.join(dir,`naghnoogh-${stamp}.sqlite`);
  await backupDatabase(destination);
  const files=(await fs.readdir(dir)).filter(x=>/^naghnoogh-.*\.sqlite$/.test(x));
  const dated=await Promise.all(files.map(async name=>({name,mtime:(await fs.stat(path.join(dir,name))).mtimeMs})));
  dated.sort((a,b)=>b.mtime-a.mtime);
  for(const old of dated.slice(7))await fs.unlink(path.join(dir,old.name)).catch(()=>{});
  console.log(`Automatic database backup saved: ${destination}`);
}
setTimeout(()=>createScheduledBackup().catch(e=>console.error('Automatic backup failed:',e)),15000);
