function reportPeriod(frequency,clock){const date=`${clock.year}-${clock.month}-${clock.day}`;if(frequency!=='weekly')return `day:${date}`;const monday=new Date(`${date}T12:00:00Z`);monday.setUTCDate(monday.getUTCDate()-((monday.getUTCDay()+6)%7));return `week:${monday.toISOString().slice(0,10)}`;}
function buildGroupReport(chat,title,days=7){const total=groupStats(chat),activity=groupActivitySummary(chat,days),leaders=top(chat).slice(0,3),chart=groupActivityChart(chat);const max=Math.max(1,...chart.map(x=>Number(x.messages)||0));const chartText=chart.length?chart.map(x=>`${x.day.slice(5)} ${'▰'.repeat(Math.max(0,Math.round((Number(x.messages)||0)/max*8)))} ${x.messages}`).join('\n'):'لا توجد بيانات نشاط كافية بعد.';return `📊 تقرير ${days===1?'اليومي':'الأسبوعي'} — ${title||'المجموعة'}\n\n👥 الأعضاء المسجلون: ${total.members}\n🟢 النشطون خلال ${days===1?'اليوم':'آخر 7 أيام'}: ${activity.active}\n💬 الرسائل خلال ${days===1?'اليوم':'آخر 7 أيام'}: ${activity.messages}\n🏆 مجموع نقاط الأعضاء: ${total.points}\n⚠️ مجموع الإنذارات الحالية: ${total.warnings}\n\n📈 حركة الرسائل خلال آخر 7 أيام\n${chartText}\n\n🥇 المتصدرون\n${leaders.length?leaders.map((x,i)=>`${i+1}. ${x.name||'عضو'} — ${x.points} نقطة`).join('\n'):'لا توجد نقاط مسجلة بعد.'}`;}
