async function runGroupScheduledTasks(){const clock=reportClock();if(Number(clock.minute)>5)return;for(const g of groupsWithReports()){if(Number(clock.hour)!==Number(g.report_hour??20))continue;if(g.report_frequency==='weekly'&&clock.weekday!=='Mon')continue;const key=reportPeriod(g.report_frequency,clock);if(g.report_last_sent===key)continue;try{const days=g.report_frequency==='daily'?1:7;await bot.api.sendMessage(g.id,buildGroupReport(g.id,g.title,days));markGroupReportSent(g.id,key);}catch(err){console.error(`Scheduled report failed for ${g.id}:`,err?.description||err?.message||err);}}if(clock.hour==='03'&&lastCleanupDay!==`${clock.year}-${clock.month}-${clock.day}`){const cleanupGroups=groupsWithCleanup();if(cleanupGroups.length){lastCleanupDay=`${clock.year}-${clock.month}-${clock.day}`;for(const g of cleanupGroups){try{const removed=cleanupGroupLogs(g.chat,g.retention_days);console.log(`Log cleanup for ${g.chat}:`,removed)}catch(err){console.error(`Log cleanup failed for ${g.chat}:`,err?.message||err)}}}}}
