bot.callbackQuery(/^ucfg:/,async ctx=>{const [,chatRaw,action]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);const sectionKey={security:'security',toggle:'security',warnings:'warnings',welcome:'welcome',replies:'replies',members:'members',logs:'logs',games:'games',advanced:'advanced'}[action];if(sectionKey&&!await canManageSection(ctx,chat,sectionKey))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية هذا القسم. راجع مالك المجموعة.',show_alert:true});try{const cm=await ctx.api.getChatMember(chat,ctx.from.id);if(!['creator','administrator'].includes(cm.status))return ctx.answerCallbackQuery({text:'الإعدادات للمشرفين فقط.',show_alert:true});}catch{return ctx.answerCallbackQuery({text:'ما كدرت أتحقق من صلاحيتك.',show_alert:true});}await ctx.answerCallbackQuery();const s=settings(chat);if(action==='security'){const g=groupConfig(chat);const label=(key,name,cmd)=>`${s.locks[key]?'🔒 إيقاف':'🔓 تشغيل'} ${name}`;return ctx.reply(`🛡️ حماية نغنوغ\n\nكل زر يبين الحالة، والأمر المكتوب يمه تگدر تستخدمه مباشرة.\n\n🔗 الروابط: قفل الروابط / فتح الروابط\n🖼️ الصور: قفل الصور / فتح الصور\n🎬 الفيديو: قفل الفيديو / فتح الفيديو\n🌊 الوسائط: قفل الوسائط / فتح الوسائط\n🎙️ الصوتيات: قفل الصوتيات / فتح الصوتيات\n🎭 الملصقات: قفل الملصقات / فتح الملصقات\n↪️ التحويل: قفل التحويل / فتح التحويل\n🔁 التكرار: قفل التكرار / فتح التكرار`,{reply_markup:new InlineKeyboard().text(label('links','🔗 الروابط'),'ucfg:'+chat+':toggle:links').text('قفل / فتح','ucfg:'+chat+':toggle:links').row().text(label('photos','🖼️ الصور'),'ucfg:'+chat+':toggle:photos').text('قفل / فتح','ucfg:'+chat+':toggle:photos').row().text(label('videos','🎬 الفيديو'),'ucfg:'+chat+':toggle:videos').text('قفل / فتح','ucfg:'+chat+':toggle:videos').row().text(label('media','🌊 الوسائط'),'ucfg:'+chat+':toggle:media').text('قفل / فتح','ucfg:'+chat+':toggle:media').row().text(label('audio','🎙️ الصوتيات'),'ucfg:'+chat+':toggle:audio').text('قفل / فتح','ucfg:'+chat+':toggle:audio').row().text(label('stickers','🎭 الملصقات'),'ucfg:'+chat+':toggle:stickers').text('قفل / فتح','ucfg:'+chat+':toggle:stickers').row().text(label('forward','↪️ التحويل'),'ucfg:'+chat+':toggle:forward').text('قفل / فتح','ucfg:'+chat+':toggle:forward').row().text(label('repeat','🔁 التكرار'),'ucfg:'+chat+':toggle:repeat').text('قفل / فتح','ucfg:'+chat+':toggle:repeat').row().text('⬅️ رجوع','ucfg:'+chat+':settings')});}if(action==='toggle'){const key=ctx.callbackQuery.data.split(':')[3];if(!Object.hasOwn(s.locks,key))return ctx.answerCallbackQuery({text:'إعداد الحماية غير معروف.',show_alert:true});const previous=s.locks[key];lock(chat,key,!previous);try{const chatInfo=await ctx.api.getChat(chat);const groupLocked=chatInfo.permissions?.can_send_messages===false;await applyProtectionPermissions(ctx,chat,settings(chat).locks,{groupLocked});logAdmin(chat,ctx.from.id,!previous?`تفعيل قفل ${key}`:`فتح قفل ${key}`);const fresh=settings(chat);await ctx.answerCallbackQuery({text:'تم تحديث الحماية ✅'});return ctx.editMessageText(`🛡️ إعدادات الحماية\n\nتم حفظ التغيير وتطبيق صلاحيات المجموعة.`,{reply_markup:new InlineKeyboard().text(`${fresh.locks.links?'🔒':'🔓'} الروابط`,`ucfg:${chat}:toggle:links`).text(`${fresh.locks.photos?'🔒':'🔓'} الصور`,`ucfg:${chat}:toggle:photos`).row().text(`${fresh.locks.videos?'🔒':'🔓'} الفيديو`,`ucfg:${chat}:toggle:videos`).text(`${fresh.locks.media?'🔒':'🔓'} الوسائط`,`ucfg:${chat}:toggle:media`).row().text(`${fresh.locks.audio?'🔒':'🔓'} الصوتيات`,`ucfg:${chat}:toggle:audio`).text(`${fresh.locks.stickers?'🔒':'🔓'} الملصقات`,`ucfg:${chat}:toggle:stickers`).row().text(`${fresh.locks.forward?'🔒':'🔓'} التحويل`,`ucfg:${chat}:toggle:forward`).text(`${fresh.locks.repeat?'🔒':'🔓'} التكرار`,`ucfg:${chat}:toggle:repeat`).row().text('⬅️ رجوع','ucfg:'+chat+':settings')});}catch(e){lock(chat,key,previous);console.error('Dashboard protection update failed:',e?.description||e?.message||e);await ctx.answerCallbackQuery({text:'تعذر تطبيق الصلاحيات. تأكد أن نغنوغ مشرف ولديه صلاحية تقييد الأعضاء.',show_alert:true});return;}}if(action==='warnings')return ctx.reply(`⚠️ إعدادات الإنذارات\n\nالحد الحالي: ${s.maxwarn||5}\nالعقوبة: ${{mute:'كتم',kick:'طرد',warn:'تحذير'}[s.punishment||'mute']||'كتم'}\nمدة الكتم: ${s.duration||30} دقيقة\n\nالأوامر: عدد الانذارات 10 • عقوبة الانذارات كتم • مدة العقوبة 15`,{reply_markup:new InlineKeyboard().text('5️⃣','cfgp:'+chat+':max:5').text('🔟','cfgp:'+chat+':max:10').text('1️⃣5️⃣','cfgp:'+chat+':max:15').text('2️⃣0️⃣','cfgp:'+chat+':max:20').row().text('🔇 كتم','cfgp:'+chat+':punish:mute').text('🚪 طرد','cfgp:'+chat+':punish:kick').text('⚠️ تحذير','cfgp:'+chat+':punish:warn').row().text('3 د','cfgp:'+chat+':duration:3').text('5 د','cfgp:'+chat+':duration:5').text('10 د','cfgp:'+chat+':duration:10').row().text('15 د','cfgp:'+chat+':duration:15').text('30 د','cfgp:'+chat+':duration:30').row().text('⬅️ رجوع','ucfg:'+chat+':settings')});if(action==='settings')return ctx.reply('⚙️ إعدادات نغنوغ\n\nاختار القسم:',{reply_markup:new InlineKeyboard().text('🛡️ الحماية',`ucfg:${chat}:security`).row().text('⚠️ الإنذارات',`ucfg:${chat}:warnings`).text('👋 الترحيب',`ucfg:${chat}:welcome`).row().text('💬 الردود التلقائية',`ucfg:${chat}:replies`).text('👥 الأعضاء',`ucfg:${chat}:members`).row().text('📋 سجل الإدارة',`ucfg:${chat}:logs`).text('🎮 الألعاب والنقاط',`ucfg:${chat}:games`).row().text('🧰 أدوات متقدمة',`ucfg:${chat}:advanced`)});if(action==='replies'){const gc=groupConfig(chat),rows=listReplies(chat);return ctx.reply(`💬 الردود التلقائية\n\nالحالة: ${gc.auto_replies?'🟢 مفعّلة':'🔴 متوقفة'}\n\n${rows.length?rows.map(x=>`#${x.id} — ${x.trigger} → ${safeJson(x.responses).join(' / ')}`).join('\n'):'ماكو ردود خاصة مضافة بعد.'}`,{reply_markup:new InlineKeyboard().text(gc.auto_replies?'🔕 إيقاف الردود':'🔔 تشغيل الردود',`ureply:toggle:${chat}`).row().text('➕ إضافة رد',`ureply:add:${chat}`).text('🗑 حذف رد',`ureply:del:${chat}`).row().text('🔄 تحديث',`ucfg:${chat}:replies`).text('⬅️ رجوع',`ucfg:${chat}:settings`)});}if(action==='members'){const a=groupMembers(chat),st=groupStats(chat);const kb=new InlineKeyboard();for(const x of a.slice(0,20))kb.text((x.name||'عضو').slice(0,24),`umember:${chat}:${x.user}`).row();kb.text('⬅️ رجوع',`usrgroup:${chat}`);return ctx.reply(`👥 لوحة أعضاء المجموعة\n\nالأعضاء المسجلون: ${st.members}\nإجمالي الرسائل: ${st.messages}\nمجموع النقاط: ${st.points}\nالإنذارات المسجلة: ${st.warnings}\n\nاختار عضواً لعرض ملفه:`,{reply_markup:kb});}if(action==='welcome'){const gc=groupConfig(chat);return ctx.reply(`👋 إعدادات الترحيب\n\nالحالة: ${gc.welcome?'🟢 مفعّل':'🔴 متوقف'}\nالنص الحالي: ${gc.welcome_text||'الترحيب الافتراضي'}\n\nالمتغيرات المتاحة: {name} و {id} و {username}`,{reply_markup:new InlineKeyboard().text(gc.welcome?'🔕 إيقاف الترحيب':'🔔 تشغيل الترحيب',`uwelcome:${chat}:toggle`).row().text('✏️ تعديل رسالة الترحيب',`uwelcome:${chat}:edit`).text('🗑 حذف النص المخصص',`uwelcome:${chat}:clear`).row().text('⬅️ رجوع',`usrgroup:${chat}`)});}if(action==='logs'){const a=adminLogs(chat);return ctx.reply(a.length?`📋 آخر عمليات الإدارة\n\n${a.map(x=>`• ${x.action}${x.target?` — ${x.target}`:''}`).join('\n')}`:'ماكو عمليات إدارية بعد.');}if(action==='games'){return ctx.reply(gameMenuText(),{reply_markup:gameMenuKeyboard()});}});
bot.callbackQuery(/^cfgp:/,async ctx=>{const [,chatRaw,action,value]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);if(!await canManageSection(ctx,chat,'warnings'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية إعدادات الإنذارات.',show_alert:true});if(action==='max')set(chat,'maxwarn',Number(value));if(action==='punish')set(chat,'punishment',value);if(action==='duration')set(chat,'duration',Number(value));await ctx.answerCallbackQuery({text:'تم الحفظ ✅'});return ctx.reply('⚠️ تم تحديث إعداد الإنذارات.',{reply_markup:new InlineKeyboard().text('⚠️ فتح إعدادات الإنذارات',`ucfg:${chat}:warnings`).text('⬅️ الإعدادات','ucfg:'+chat+':settings')});});
bot.callbackQuery(/^ureply:/,async ctx=>{const [,action,chatRaw]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);if(!await canManageSection(ctx,chat,'replies'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية الردود التلقائية.',show_alert:true});await ctx.answerCallbackQuery();if(action==='toggle'){const gc=groupConfig(chat);setGroupConfig(chat,'auto_replies',gc.auto_replies?0:1);return ctx.reply(`💬 الردود التلقائية: ${groupConfig(chat).auto_replies?'🟢 مفعّلة':'🔴 متوقفة'}`,{reply_markup:new InlineKeyboard().text('⬅️ رجوع للردود','ucfg:'+chat+':replies')});}if(action==='add'){ownerState.set(ctx.from.id,{mode:'add_reply',chat});return ctx.reply('➕ إضافة رد\n\nدزها بهذا الشكل:\nالكلمة | الرد الأول | الرد الثاني\n\nمثال:\nهلا | هلا بيك ❤️ | يا مية هلا 🌹');}if(action==='del'){ownerState.set(ctx.from.id,{mode:'del_reply',chat});return ctx.reply('🗑 دز رقم الرد المراد حذفه.');}});
bot.callbackQuery(/^pgroup:/,async ctx=>{const [,chatRaw,action]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);try{const cm=await ctx.api.getChatMember(chat,ctx.from.id);if(!['creator','administrator'].includes(cm.status))return ctx.answerCallbackQuery({text:'الإعدادات للمشرفين فقط.',show_alert:true});}catch{return ctx.answerCallbackQuery({text:'ما كدرت أتحقق من صلاحيتك.',show_alert:true});}await ctx.answerCallbackQuery();return ctx.reply(`⚙️ ${action==='settings'?'إعدادات نغنوغ':action==='security'?'الحماية':action==='replies'?'الردود التلقائية':action==='warnings'?'الإنذارات':action==='welcome'?'الترحيب':action==='members'?'الأعضاء':action==='logs'?'سجل الإدارة':action==='games'?'الألعاب والنقاط':'الأدوات المتقدمة'}\n\nاختار القسم:`,{reply_markup:new InlineKeyboard().text('🛡️ الحماية',`ucfg:${chat}:security`).row().text('⚠️ الإنذارات',`ucfg:${chat}:warnings`).text('👋 الترحيب',`ucfg:${chat}:welcome`).row().text('💬 الردود التلقائية',`ucfg:${chat}:replies`).text('👥 الأعضاء',`ucfg:${chat}:members`).row().text('📋 سجل الإدارة',`ucfg:${chat}:logs`).text('🎮 الألعاب',`ucfg:${chat}:games`).row().text('🧰 أدوات متقدمة',`ucfg:${chat}:advanced`)});});
bot.callbackQuery(/^usrgroup:/,async ctx=>{const chat=Number(ctx.callbackQuery.data.split(':')[1]);try{const cm=await ctx.api.getChatMember(chat,ctx.from.id);if(!['creator','administrator'].includes(cm.status))return ctx.answerCallbackQuery({text:'الإعدادات للمشرفين فقط.',show_alert:true});}catch{return ctx.answerCallbackQuery({text:'ما كدرت أتحقق من صلاحيتك.',show_alert:true});}await ctx.answerCallbackQuery();return ctx.reply(`⚙️ إدارة مجموعة ${chat}\n\nاختار القسم:`,{reply_markup:new InlineKeyboard().text('🛡️ الحماية',`ucfg:${chat}:security`).row().text('⚠️ الإنذارات',`ucfg:${chat}:warnings`).text('👋 الترحيب',`ucfg:${chat}:welcome`).row().text('💬 الردود التلقائية',`ucfg:${chat}:replies`).text('👥 الأعضاء',`ucfg:${chat}:members`).row().text('📋 سجل الإدارة',`ucfg:${chat}:logs`).text('🎮 الألعاب',`ucfg:${chat}:games`).row().text('🧰 أدوات متقدمة',`ucfg:${chat}:advanced`)});});
bot.callbackQuery(/^umember:/,async ctx=>{const [,chatRaw,userRaw]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw),target=Number(userRaw);if(!await canManageSection(ctx,chat,'members'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية إدارة الأعضاء.',show_alert:true});await ctx.answerCallbackQuery();return ctx.reply(memberManagementText(chat,target),{reply_markup:memberManagementKeyboard(chat,target)});});
bot.callbackQuery(/^umod:/,async ctx=>{const [,chatRaw,userRaw,action]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw),target=Number(userRaw);if(!Number.isSafeInteger(chat)||!Number.isSafeInteger(target)||target<=0)return ctx.answerCallbackQuery({text:'بيانات العضو غير صحيحة.',show_alert:true});if(!await canManageSection(ctx,chat,'members'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية إدارة الأعضاء.',show_alert:true});let targetMember;try{targetMember=await ctx.api.getChatMember(chat,target);}catch{return ctx.answerCallbackQuery({text:'تعذر العثور على العضو في المجموعة.',show_alert:true});}if(['creator','administrator'].includes(targetMember.status))return ctx.answerCallbackQuery({text:'لا يمكن تنفيذ هذا الإجراء على مالك المجموعة أو أحد مشرفيها.',show_alert:true});if(targetMember.user?.is_bot)return ctx.answerCallbackQuery({text:'لا يمكن تطبيق إدارة الأعضاء على حساب بوت.',show_alert:true});let successText='تم تنفيذ الإجراء.';try{const cfg=settings(chat);if(action==='warn'){const count=warn(chat,target);addModerationEvent(chat,target,ctx.from.id,'إنذار','إنذار من لوحة إدارة المجموعة');logAdmin(chat,ctx.from.id,'إنذار من لوحة الأعضاء',target);if(count>=(cfg.maxwarn||5)){const kind=cfg.punishment||'mute',mins=cfg.duration||30;if(kind==='mute'){await ctx.api.restrictChatMember(chat,target,{until_date:Math.floor(Date.now()/1000)+mins*60,permissions:{can_send_messages:false}});addModerationEvent(chat,target,ctx.from.id,'كتم تلقائي','بلوغ حد الإنذارات',mins,Math.floor(Date.now()/1000)+mins*60);}else if(kind==='kick'){await ctx.api.banChatMember(chat,target);await ctx.api.unbanChatMember(chat,target);addModerationEvent(chat,target,ctx.from.id,'طرد تلقائي','بلوغ حد الإنذارات');}else if(kind==='ban'){await ctx.api.banChatMember(chat,target);groupBan(chat,target,'بلوغ حد الإنذارات');addModerationEvent(chat,target,ctx.from.id,'حظر تلقائي','بلوغ حد الإنذارات');}if(kind!=='warn')resetWarnings(chat,target);}successText=`تم تسجيل الإنذار ${count}/${cfg.maxwarn||5} ✅`;}else if(action==='mute'){const until=Math.floor(Date.now()/1000)+30*60;await ctx.api.restrictChatMember(chat,target,{until_date:until,permissions:{can_send_messages:false}});addModerationEvent(chat,target,ctx.from.id,'كتم','كتم من لوحة إدارة الأعضاء',30,until);logAdmin(chat,ctx.from.id,'كتم من لوحة الأعضاء',target,'30 دقيقة');successText='تم كتم العضو لمدة 30 دقيقة ✅';}else if(action==='unmute'){const chatInfo=await ctx.api.getChat(chat);const restoredPermissions={can_send_messages:true,can_send_audios:true,can_send_documents:true,can_send_photos:true,can_send_videos:true,can_send_video_notes:true,can_send_voice_notes:true,can_send_other_messages:true,can_add_web_page_previews:true,can_send_polls:true,...(chatInfo.permissions||{})};await ctx.api.restrictChatMember(chat,target,{permissions:restoredPermissions});addModerationEvent(chat,target,ctx.from.id,'إلغاء كتم','إلغاء من لوحة إدارة الأعضاء');logAdmin(chat,ctx.from.id,'إلغاء كتم من لوحة الأعضاء',target);successText='تم إلغاء الكتم ✅';}else if(action==='kick'){await ctx.api.banChatMember(chat,target);await ctx.api.unbanChatMember(chat,target);addModerationEvent(chat,target,ctx.from.id,'طرد','طرد من لوحة إدارة الأعضاء');logAdmin(chat,ctx.from.id,'طرد من لوحة الأعضاء',target);successText='تم طرد العضو ✅';}else if(action==='ban'){await ctx.api.banChatMember(chat,target);groupBan(chat,target,'حظر من لوحة إدارة الأعضاء');addModerationEvent(chat,target,ctx.from.id,'حظر','حظر من لوحة إدارة الأعضاء');logAdmin(chat,ctx.from.id,'حظر من لوحة الأعضاء',target);successText='تم حظر العضو ✅';}else if(action==='reset'){resetWarnings(chat,target);addModerationEvent(chat,target,ctx.from.id,'تصفير الإنذارات','تصفير من لوحة إدارة الأعضاء');logAdmin(chat,ctx.from.id,'تصفير إنذارات من لوحة الأعضاء',target);successText='تم تصفير الإنذارات ✅';}else return ctx.answerCallbackQuery({text:'إجراء غير معروف.',show_alert:true});await ctx.editMessageText(memberManagementText(chat,target),{reply_markup:memberManagementKeyboard(chat,target)});return ctx.answerCallbackQuery({text:successText});}catch(e){console.error('Member dashboard action failed:',e?.description||e?.message||e);return ctx.answerCallbackQuery({text:'تعذر تنفيذ الإجراء. تأكد من صلاحيات نغنوغ في المجموعة.',show_alert:true});}});
bot.callbackQuery(/^uadv:/,async ctx=>{const [,chatRaw,action]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);if(!await canManageSection(ctx,chat,'advanced'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية الأدوات المتقدمة.',show_alert:true});const gc=groupConfig(chat);if(action==='bot')setGroupConfig(chat,'anti_bot',gc.anti_bot?0:1);if(action==='filter')setGroupConfig(chat,'word_filter',gc.word_filter?0:1);if(action==='service')setGroupConfig(chat,'service_messages',gc.service_messages?0:1);if(action==='replies')setGroupConfig(chat,'auto_replies',gc.auto_replies?0:1);if(action==='flood')setGroupConfig(chat,'anti_flood',gc.anti_flood?0:1);if(['bot','filter','service','replies','flood'].includes(action))logAdmin(chat,ctx.from.id,'تحديث أداة متقدمة',null,action);await ctx.answerCallbackQuery();return ctx.editMessageText('🧰 تم تحديث الأدوات المتقدمة.',{reply_markup:new InlineKeyboard().text('🧰 عرض الأدوات',`ucfg:${chat}:advanced`).row().text('⬅️ رجوع',`usrgroup:${chat}`)});});
bot.callbackQuery(/^ublock:/,async ctx=>{const [,action,chatRaw]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);if(!await canManageSection(ctx,chat,'advanced'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية الأدوات المتقدمة.',show_alert:true});await ctx.answerCallbackQuery();if(action==='add'){ownerState.set(ctx.from.id,{mode:'blocked_word',chat});return ctx.reply('🚫 اكتب الكلمة الممنوعة فقط، مثال:\nسبام');}if(action==='list'){const a=blockedWords(chat);return ctx.reply(a.length?`🚫 الكلمات الممنوعة (${a.length})\\n\\n${a.map((x,i)=>`${i+1}. ${x.word}`).join('\\n')}`:'🚫 ماكو كلمات ممنوعة بعد.',{reply_markup:new InlineKeyboard().text('➕ إضافة كلمة',`ublock:add:${chat}`).row().text('⬅️ رجوع',`ucfg:${chat}:advanced`)});}});
bot.callbackQuery(/^uwelcome:/,async ctx=>{const [,chatRaw,action]=ctx.callbackQuery.data.split(':');const chat=Number(chatRaw);if(!await canManageSection(ctx,chat,'welcome'))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية الترحيب.',show_alert:true});if(action==='edit'){ownerState.set(ctx.from.id,{mode:'welcome_text',chat});await ctx.answerCallbackQuery();return ctx.reply('✏️ دز رسالة الترحيب الجديدة.\n\nتگدر تستخدم المتغيرات:\n{name} اسم العضو\n{id} ايدي العضو\n{username} معرف العضو\n\nالحد الأقصى 1000 حرف.');}if(action==='clear'){setGroupConfig(chat,'welcome_text','');logAdmin(chat,ctx.from.id,'حذف نص الترحيب المخصص');await ctx.answerCallbackQuery({text:'تم حذف النص المخصص ✅'});return ctx.editMessageText('👋 تم حذف نص الترحيب المخصص. سيستخدم نغنوغ رسالة الترحيب الافتراضية.',{reply_markup:new InlineKeyboard().text('⬅️ إعدادات الترحيب',`ucfg:${chat}:welcome`).row().text('⬅️ إدارة المجموعة',`usrgroup:${chat}`)});}if(action==='toggle'){setGroupConfig(chat,'welcome',groupConfig(chat).welcome?0:1);logAdmin(chat,ctx.from.id,'تغيير حالة الترحيب',null,groupConfig(chat).welcome?'تشغيل':'إيقاف');await ctx.answerCallbackQuery({text:'تم تحديث الترحيب ✅'});return ctx.editMessageText(`👋 الترحيب الآن: ${groupConfig(chat).welcome?'🟢 مفعّل':'🔴 متوقف'}`,{reply_markup:new InlineKeyboard().text('⚙️ إعدادات الترحيب',`ucfg:${chat}:welcome`).row().text('⬅️ إدارة المجموعة',`usrgroup:${chat}`)});}return ctx.answerCallbackQuery({text:'خيار غير معروف.',show_alert:true});});
bot.callbackQuery(/^uperm:/,async ctx=>{const bits=ctx.callbackQuery.data.split(':');if(bits[1]==='close'){await ctx.answerCallbackQuery();try{return await ctx.deleteMessage()}catch{return}}const chat=Number(bits[1]),target=Number(bits[2]),key=bits[3];if(!Number.isSafeInteger(chat)||!Number.isSafeInteger(target))return ctx.answerCallbackQuery({text:'بيانات غير صحيحة.',show_alert:true});if(!await isGroupCreator(ctx,chat))return ctx.answerCallbackQuery({text:'مالك المجموعة فقط يستطيع تعديل صلاحيات المشرفين.',show_alert:true});let tm;try{tm=await ctx.api.getChatMember(chat,target)}catch{return ctx.answerCallbackQuery({text:'تعذر التحقق من المشرف.',show_alert:true})}if(tm.status!=='administrator')return ctx.answerCallbackQuery({text:'هذا المستخدم لم يعد مشرفاً في المجموعة.',show_alert:true});if(key==='reset'){resetAdminPermissions(chat,target);logAdmin(chat,ctx.from.id,'إعادة صلاحيات مشرف',target);await ctx.answerCallbackQuery({text:'تمت إعادة جميع الصلاحيات ✅'});}else{if(!Object.hasOwn(permissionLabels,key))return ctx.answerCallbackQuery({text:'صلاحية غير معروفة.',show_alert:true});const enabled=toggleAdminPermission(chat,target,key);logAdmin(chat,ctx.from.id,enabled?'منح صلاحية مشرف':'سحب صلاحية مشرف',target,permissionLabels[key]);await ctx.answerCallbackQuery({text:enabled?'تم منح الصلاحية ✅':'تم سحب الصلاحية 🔒'});}return ctx.editMessageText(adminPermissionText(chat,target),{reply_markup:adminPermissionKeyboard(chat,target)});});

bot.callbackQuery(/^game:/,async ctx=>{
  const bits=ctx.callbackQuery.data.split(':');
  if(bits[1]==='opt'){const gameId=Number(bits[2]);const choice=Buffer.from(bits[3],'base64url').toString();const g=gameById(gameId);if(!g?.active)return ctx.answerCallbackQuery({text:'الجولة خلصت.',show_alert:true});if(normalizeAnswer(choice)!==normalizeAnswer(g.answer))return ctx.answerCallbackQuery({text:'مو هذا الجواب 😅 جرّب غيره.',show_alert:true});finishGame(gameId);points(ctx.chat.id,ctx.from.id,2);await ctx.answerCallbackQuery({text:'صح! ربحت +2 🏆',show_alert:true});await grantEligibleAchievements(ctx,ctx.chat.id,ctx.from.id);return ctx.reply(`عفية ${name(ctx.from)}! 🎉\nجاوبت صح وربحت 2🏆`);}
  const action=bits[1];
  if(action==='info'){
    const type=bits[2];
    if(!isGroup(ctx.chat))return ctx.answerCallbackQuery({text:'ابدأ الألعاب من داخل المجموعة حتى يشارك الجميع.',show_alert:true});
    await ctx.answerCallbackQuery({text:gameRulesText(type),show_alert:true});
    return startGame(ctx,type);
  }
  if(action==='rules'){
    const type=bits[2]||null;
    return ctx.answerCallbackQuery({text:gameRulesText(type),show_alert:true});
  }
  if(action==='start'){
    await ctx.answerCallbackQuery({text:'🎮 انفتحت جولة جديدة!',show_alert:false});
    return startGame(ctx,bits[2]||'mean');
  }
  if(action==='score'){
    return ctx.answerCallbackQuery({text:`🏆 نقاطك: ${member(ctx.chat.id,ctx.from.id).points||0} نقطة`,show_alert:true});
  }
  return ctx.answerCallbackQuery();
});
bot.callbackQuery(/^start:/,async ctx=>{
  if(ctx.chat?.type!=='private')return ctx.answerCallbackQuery({text:'هذا الزر للخاص ويا نغنوغ.',show_alert:true});
  const action=ctx.callbackQuery.data.split(':')[1];
  await ctx.answerCallbackQuery();
  if(action==='add'){
    const me=await ctx.api.getMe();
    return ctx.reply('اضغط الرابط واختار المجموعة، وبعدها ارفعني مشرف حتى أشتغل:',{reply_markup:new InlineKeyboard().url('➕ إضافة نغنوغ',`https://t.me/${me.username}?startgroup=true`)});
  }
  if(action==='groups'){
    const gs=userGroups(ctx.from.id);
    if(!gs.length)return ctx.reply('بعد ما عندك مجموعات مسجلة وياي. ضيفني لمجموعة وخليني مشرف.');
    return ctx.reply('هاي مجموعاتك. اختار المجموعة:',{reply_markup:groupMenuKeyboard(gs,'settings')});
  }
  return ctx.reply(mainText(),{reply_markup:mainInlineKeyboard()});
});
bot.callbackQuery(/^own:/,async ctx=>{
 if(ctx.from.id!==OWNER||ctx.chat?.type!=='private')return ctx.answerCallbackQuery({text:'هاي اللوحة للمالك بس.'});
 await ctx.answerCallbackQuery();
 const bits=ctx.callbackQuery.data.split(':'); const a=bits[1];
 if(a==='home')return ctx.editMessageText('🤖 نغنوغ 🇮🇶\nلوحة تحكم المالك — اختار القسم:',{reply_markup:ownerKeyboard()});
 if(a==='backup')return sendOwnerBackup(ctx);
 if(a==='restore'){ownerState.set(ctx.from.id,{mode:'restore'});return ctx.reply('♻️ أرسل ملف قاعدة بيانات نغنوغ بصيغة .sqlite أو .db (حتى 20 ميغابايت). سيتم فحصه وتجهيزه للتطبيق عند إعادة تشغيل البوت، مع حفظ نسخة من القاعدة الحالية.');}
 if(a==='resolve'){resolveReport(Number(bits[2]));return ctx.reply('✅ تم إغلاق البلاغ.');}
 if(a==='reportmute'){const [id,chat,target]=[Number(bits[2]),Number(bits[3]),Number(bits[4])];try{await ctx.api.restrictChatMember(chat,target,{until_date:Math.floor(Date.now()/1000)+1800,permissions:{can_send_messages:false}});resolveReport(id);return ctx.reply('🔇 تم كتم العضو 30 دقيقة وإغلاق البلاغ.')}catch{return ctx.reply('⚠️ ما كدرت أكتم العضو. تأكد من صلاحيات نغنوغ بالمجموعة.')}}
 if(a==='reportban'){const [id,chat,target]=[Number(bits[2]),Number(bits[3]),Number(bits[4])];try{await ctx.api.banChatMember(chat,target);resolveReport(id);return ctx.reply('🚫 تم حظر العضو وإغلاق البلاغ.')}catch{return ctx.reply('⚠️ ما كدرت أحظر العضو. تأكد من صلاحيات نغنوغ بالمجموعة.')}}
 if(a==='stats'){const x=stats();return ctx.reply(`📊 إحصائيات البوت\n👥 المستخدمون المسجلون: ${x.users}\n💬 مستخدمو الخاص: ${x.privateUsers}\n🏘️ المجموعات النشطة: ${x.groups}\n🏆 مجموع النقاط: ${x.points}\n⛔ المستخدمون المحظورون: ${x.blocked}\n🚩 البلاغات الجديدة: ${x.reports}`,{reply_markup:new InlineKeyboard().text('⬅️ لوحة المالك','own:home')});}
 if(a==='users'){const list=users();const body=list.length?list.map((x,i)=>`${i+1}) ${x.name||'بدون اسم'} — ${x.id}${x.username?' @'+x.username:''}`).join('\n'):'ماكو مستخدمين مسجلين بعد.';return ctx.reply(`👥 آخر المستخدمين المسجلين\n${body}\n\nللمراسلة اضغط الزر أو استخدم /مراسلة USER_ID`,{reply_markup:new InlineKeyboard().text('✉️ مراسلة مستخدم','own:dm').row().text('⬅️ رجوع','own:home')});}
 if(a==='groups'){const list=groups();const body=list.length?list.map((x,i)=>`${i+1}) ${x.title||'مجموعة'} — ${x.id}`).join('\n'):'ماكو مجموعات نشطة مسجلة.';return ctx.reply(`🏘️ المجموعات المسجلة\n${body}`,{reply_markup:new InlineKeyboard().text('⬅️ رجوع','own:home')});}
 if(a==='dm'){ownerState.set(ctx.from.id,{mode:'dm_target'});return ctx.reply('دز رقم Telegram ID للمستخدم اللي تريد تراسله:');}
 if(a==='banuser'){ownerState.set(ctx.from.id,{mode:'bot_ban'});return ctx.reply('⛔ دز Telegram ID للمستخدم المراد منعه من استعمال نغنوغ.\nتگدر تضيف سبب بعد الرقم، مثال: 123456789 سبام.');}
 if(a==='banned'){const list=botBans();if(!list.length)return ctx.reply('ماكو مستخدمين محظورين من البوت حالياً.',{reply_markup:new InlineKeyboard().text('⬅️ رجوع','own:home')});for(const x of list)await ctx.reply(`⛔ المستخدم: ${x.user}\nالسبب: ${x.reason||'غير محدد'}`,{reply_markup:new InlineKeyboard().text('🔓 إلغاء الحظر',`own:unbanuser:${x.user}`)});return;}
 if(a==='unbanuser'){const id=Number(bits[2]);botUnban(id);return ctx.reply(`✅ تم إلغاء منع المستخدم ${id} من استعمال نغنوغ.`);}
 if(a==='addchannel'){ownerState.set(ctx.from.id,{mode:'channel'});return ctx.reply('دز معرف القناة مثل @MyChannel، وإذا رابط الدعوة مختلف اكتبه بعد مسافة.\nمثال: @MyChannel https://t.me/MyChannel',{reply_markup:new InlineKeyboard().text('إلغاء','own:home')});}
 if(a==='channels'){const list=mandatoryChannels();if(!list.length)return ctx.reply('ماكو قنوات اشتراك إجباري حالياً.',{reply_markup:new InlineKeyboard().text('➕ إضافة قناة','own:addchannel').row().text('⬅️ رجوع','own:home')});for(const x of list)await ctx.reply(`📢 ${x.chat_id}\nرابط الاشتراك: ${x.invite}`,{reply_markup:new InlineKeyboard().text('🗑 حذف القناة',`own:delchannel:${x.id}`)});return ctx.reply('إدارة قنوات الاشتراك:',{reply_markup:new InlineKeyboard().text('➕ إضافة قناة','own:addchannel').row().text('⬅️ رجوع','own:home')});}
 if(a==='delchannel'){removeMandatoryChannel(Number(bits[2]));return ctx.reply('تم حذف القناة من قائمة الاشتراك الإجباري.',{reply_markup:new InlineKeyboard().text('عرض القنوات','own:channels').row().text('⬅️ لوحة المالك','own:home')});}
 if(a==='broadcast'){ownerState.set(ctx.from.id,{mode:'broadcast'});return ctx.reply('📣 الإذاعة العامة\n\nدز الرسالة هسه، وأنا أوصلها للمستخدمين والمجموعات المسجلة عند نغنوغ.\n\n⚠️ الإذاعة قد تستغرق وقت حسب عدد الجهات حتى ما ننضرب بحدود Telegram.');}
 if(a==='reports'){const list=pendingReports();if(!list.length)return ctx.reply('ماكو بلاغات جديدة، اللمة هادئة 😌',{reply_markup:new InlineKeyboard().text('⬅️ رجوع','own:home')});for(const x of list)await ctx.reply(`🚩 بلاغ #${x.id}\n\n🏘️ المجموعة: ${x.chat}\n👤 المبلّغ: ${x.reporter}\n⚠️ العضو: ${x.target}\n📝 الرسالة: ${x.message}`,{reply_markup:new InlineKeyboard().text('🔇 كتم 30د',`own:reportmute:${x.id}:${x.chat}:${x.target}`).row().text('🚫 حظر',`own:reportban:${x.id}:${x.chat}:${x.target}`).text('✅ إغلاق',`own:resolve:${x.id}`)});return;}
});
bot.callbackQuery(/^cfg:/,async ctx=>{if(!isGroup(ctx.chat)||!(await admin(ctx)))return ctx.answerCallbackQuery({text:'هاي الإعدادات للمشرفين بس.'});const bits=ctx.callbackQuery.data.split(':');const action=bits[1];const chat=ctx.chat.id;const need={toggle:'security',security:'security',max:'warnings',punish:'warnings',duration:'warnings',warnings:'warnings',members:'members',replies:'replies',games:'games',advanced:'advanced'}[action];if(need&&!await canManageSection(ctx,chat,need))return ctx.answerCallbackQuery({text:'⛔ لا تملك صلاحية هذا القسم.',show_alert:true});let s=settings(chat);await ctx.answerCallbackQuery();if(action==='toggle'){const key=bits[2];if(!Object.hasOwn(s.locks,key))return;lock(chat,key,!s.locks[key]);s=settings(chat);return ctx.editMessageText('🛡️ إعدادات الحماية\n\nالأوامر: قفل الروابط / فتح الروابط • قفل الصور / فتح الصور • قفل الفيديو / فتح الفيديو • قفل الوسائط / فتح الوسائط • قفل الصوتيات / فتح الصوتيات • قفل الملصقات / فتح الملصقات • قفل التحويل / فتح التحويل • قفل التكرار / فتح التكرار', {reply_markup:securityKeyboard(s)});}if(action==='max'){set(chat,'maxwarn',Number(bits[2]));s=settings(chat);return ctx.editMessageText(`⚠️ عدد الإنذارات قبل العقوبة: ${s.maxwarn}`,{reply_markup:warningKeyboard(s)});}if(action==='punish'){set(chat,'punishment',bits[2]);s=settings(chat);return ctx.editMessageText(`⚠️ تم اختيار العقوبة: ${{mute:'كتم',kick:'طرد',warn:'تحذير'}[s.punishment]||'كتم'}`,{reply_markup:warningKeyboard(s)});}if(action==='duration'){set(chat,'duration',Number(bits[2]));s=settings(chat);return ctx.editMessageText(`⏱️ مدة العقوبة: ${s.duration} دقيقة`,{reply_markup:warningKeyboard(s)});}if(action==='noop')return;if(action==='home')return ctx.editMessageText('⚙️ اختار القسم:',{reply_markup:new InlineKeyboard().text('🛡️ الحماية','cfg:security').row().text('💬 الردود التلقائية','cfg:replies').text('⚠️ الإنذارات','cfg:warnings').row().text('👥 إحصائيات الأعضاء','cfg:members').row().text('🎮 الألعاب والنقاط','cfg:games')});if(action==='security')return ctx.editMessageText('🛡️ إعدادات الحماية\n\nالأوامر: قفل الروابط / فتح الروابط • قفل الصور / فتح الصور • قفل الفيديو / فتح الفيديو • قفل الوسائط / فتح الوسائط • قفل الصوتيات / فتح الصوتيات • قفل الملصقات / فتح الملصقات • قفل التحويل / فتح التحويل • قفل التكرار / فتح التكرار', {reply_markup:securityKeyboard(s)});if(action==='warnings')return ctx.editMessageText('⚠️ إعدادات الإنذارات والعقوبات:',{reply_markup:warningKeyboard(s)});if(action==='members'){const a=groupMembers(chat);return ctx.reply(a.length?a.map((x,i)=>`${i+1}. ${x.name||'عضو'} — ${x.messages} رسالة — ${x.points} نقطة — ${x.warnings} إنذار`).join('\n'):'ماكو بيانات أعضاء بعد.');}if(action==='replies')return ctx.reply(`الردود الخاصة:\n${listReplies(chat).map(x=>`#${x.id} ${x.trigger}`).join('\n')||'بعد ماكو ردود خاصة.'}\n\nإضافة: اضف رد الكلمة | الرد الأول | الرد الثاني\nعرض: ردودي\nحذف: حذف رد رقم`);if(action==='games')return ctx.reply('النقاط منفصلة لكل مجموعة. اكتب العاب لبدء لعبة معاني.');if(action==='advanced'){const gc=groupConfig(chat),bw=blockedWords(chat);return ctx.reply(`🧰 أدوات متقدمة\n\n🤖 مكافحة البوتات: ${gc.anti_bot?'🟢 مفعّلة':'🔴 متوقفة'}\n🚫 فلترة الكلمات: ${gc.word_filter?'🟢 مفعّلة':'🔴 متوقفة'} — ${bw.length} كلمة\n🧹 رسائل الخدمة: ${gc.service_messages?'تظهر':'تنحذف'}\n🌊 مكافحة الإغراق: ${gc.anti_flood?'مفعّلة':'متوقفة'}`,{reply_markup:new InlineKeyboard().text(gc.anti_bot?'🔕 إيقاف البوتات':'🤖 تشغيل مكافحة البوتات',`uadv:${chat}:bot`).row().text(gc.word_filter?'🔕 إيقاف الفلترة':'🚫 تشغيل فلترة الكلمات',`uadv:${chat}:filter`).row().text('➕ إضافة كلمة ممنوعة',`ublock:add:${chat}`).text('📋 الكلمات الممنوعة',`ublock:list:${chat}`).row().text(gc.service_messages?'🧹 إخفاء رسائل الخدمة':'💬 إظهار رسائل الخدمة',`uadv:${chat}:service`).row().text(gc.auto_replies?'🔕 إيقاف الردود':'💬 تشغيل الردود',`uadv:${chat}:replies`).row().text(gc.anti_flood?'🌊 إيقاف مكافحة الإغراق':'🌊 تشغيل مكافحة الإغراق',`uadv:${chat}:flood`).row().text('⬅️ رجوع',`ucfg:${chat}:settings`)});}});
bot.catch(e=>console.error('Bot error',e.error));bot.start({allowed_updates:['message','callback_query','my_chat_member','chat_member'],onStart:x=>console.log(`Started @${x.username} | can_read_all_group_messages=${x.can_read_all_group_messages?'yes':'no'}`)});
